INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (1, 1, "2023/06/30 12:00:00", "クローチェ", 1, 0, -470, 1.47, 2, "いらっしゃいませっ♪\nキャラバンコインを使って\n買い物ができますよっ！", 10001, 2002, 126401, "2023/09/22 14:59:59");
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (1, 2, "2023/06/30 12:00:00", "クローチェ", 2, 0, -470, 2.15, 1, "素敵な品が揃ってるので\nたーっくさん買っていって\nくださいねっ♪", 10002, 2002, 126401, "2023/09/22 14:59:59");
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (1, 1, "2023/06/30 12:00:00", "ライラエル", 2, 0, -470, 0, 2, "ショップへようこそ\nキャラバンコインはこちら\nで買い物に使えますよ", 10003, 2002, 126501, "2023/09/22 14:59:59");
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (1, 2, "2023/06/30 12:00:00", "ライラエル", 1, 0, -470, 0, 1, "こちらのショップで\n買い物をして、素敵な\n旅を楽しんでくださいね", 10004, 2002, 126501, "2023/09/22 14:59:59");
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (2, 1, "2023/09/15 15:00:00", "リンド", 2, 0, -470, 0, 2, "いらっしゃいませ\nキャラバンコインを使って\nお買い物ができますよ", 10005, 2002, 127702, "2023/12/22 14:59:59");
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (2, 2, "2023/09/15 15:00:00", "リンド", 2, 0, -470, 0, 2, "ショップの掃除は完璧です\n姫さま直営のお店として\n当然のことですから", 10006, 2002, 127702, "2023/12/22 14:59:59");
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (2, 1, "2023/09/15 15:00:00", "ヴルム", 1, 0, -470, 0, 1, "ショップへようこそ\nキャラバンコインと品物を\n交換できるんで、よければ", 10007, 2002, 127802, "2023/12/22 14:59:59");
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (2, 2, "2023/09/15 15:00:00", "ヴルム", 2, 0, -470, 6.5, 1, "なんで店番なんか…\nま、やりますけど\n好きな品物をどうぞ", 10008, 2002, 127802, "2023/12/22 14:59:59");
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (3, 1, "2023/12/15 15:00:00", "アネモネ", 2, 0, -470, 0, 1, "──いらっしゃいませ\n買い物しても、いいですよ\nキャラバンコインがあれば", 10009, 2002, 129602, "2024/03/22 14:59:59");
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (3, 2, "2023/12/15 15:00:00", "アネモネ", 2, 0, -470, 0, 1, "──もっと笑顔がほしい？\nいくらコインを積まれても\n売れない物はありますから", 10010, 2002, 129602, "2024/03/22 14:59:59");
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (3, 1, "2023/12/15 15:00:00", "ネフィ=ネラ", 1, 0, -470, 0, 1, "ようこそおいでなんし\nキャラバンコインをこちら\nで交換して進ぜんしょう", 10011, 2002, 129701, "2024/03/22 14:59:59");
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (3, 2, "2023/12/15 15:00:00", "ネフィ=ネラ", 2, 0, -470, 6.2, 1, "ところで、お前さまは\nいくらで贖えるのか喃？\n──フフ、冗談でありんす", 10012, 2002, 129701, "2024/03/22 14:59:59");
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (4, 1, "2024/03/15 15:00:00", "カノン", 3, 0, -470, 3.1, 5, "い、いらっしゃいませっ！\n…くっ…このあたくし様が\n店番なんて…屈辱ですわっ", 10013, 2002, 130301, "2024/06/22 14:59:59");
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (4, 2, "2024/03/15 15:00:00", "カノン", 3, 0, -470, 6.15, 2, "あら、あたくしをご所望？\nお生憎様、そんな小銭では\n…買えちゃうんですの！？", 10014, 2002, 130301, "2024/06/22 14:59:59");
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (4, 1, "2024/03/15 15:00:00", "ナーナ", 2, 0, -470, 0, 2, "いらっしゃいませ～♪\nきゃらばんこいん？を\n交換できるんだってー", 10015, 2002, 130401, "2024/06/22 14:59:59");
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (4, 2, "2024/03/15 15:00:00", "ナーナ", 2, 0, -470, 3.35, 1, "甘いのくれたら、\nお礼にナーナの拾った\n松ぼっくりあげちゃうよ！", 10016, 2002, 130401, "2024/06/22 14:59:59");
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (5, 1, "2024/06/15 15:00:00", "ホウオウ", 1, 0, -470, 0, 1, "ショップへようこそ\nこの鳳凰が、皆さんに\n祝福を差し上げましょう", 10017, 2002, 130502, "2024/09/22 14:59:59");
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (5, 2, "2024/06/15 15:00:00", "ホウオウ", 2, 0, -470, 3.18, 1, "ほーちゃんと呼ぶ権利は\n売っていませんよ？\n騎士さんへの、特別です！", 10018, 2002, 130502, "2024/09/22 14:59:59");
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (5, 3, "2024/06/15 15:00:00", "ホウオウ", 4, 0, -470, 0, 4, "うﾞぇぇえんっ！まﾞだごの\n格好になっぢゃいまじだ！\n寄付をお願いじまず～っ！", 10019, 2002, 130503, "2024/09/22 14:59:59");
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (5, 1, "2024/06/15 15:00:00", "ネア", 1, 0, -470, 4.9, 2, "おっすー♪\nなんでも交換してけー\nカリザきゅん以外で", 10020, 2002, 123301, "2024/09/22 14:59:59");
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (5, 2, "2024/06/15 15:00:00", "ネア", 1, 0, -470, 4.8, 2, "ところで、騎士きゅんは\nおいくら万ルピ？\nジョーダンぬ・き・で♡", 10021, 2002, 123301, "2024/09/22 14:59:59");
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (6, 1, "2024/09/15 15:00:00", "カリザ", 3, 0, -470, 4.922, 1, "ケッ、なんでオレ様が店番\nなんざ…って来んなキイロ\nオレは売りモンじゃねー！", 10022, 2002, 133301, "2024/12/22 14:59:59");
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (6, 2, "2024/09/15 15:00:00", "カリザ", 3, 0, -470, 9.638, 5, "い、言わなきゃダメか？\n「…いらっしゃいませ…」\nクソッ、笑うんじゃねー！", 10023, 2002, 133301, "2024/12/22 14:59:59");
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (6, 1, "2024/09/15 15:00:00", "ミーア", 1, 0, -470, 2.88, 2, "ショップへようこそ～\nネラさまの腹心…的な私が\n店番させていただきま～す", 10024, 2002, 133401, "2024/12/22 14:59:59");
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (6, 2, "2024/09/15 15:00:00", "ミーア", 5, 0, -470, 4.818, 1, "私の抜け殻とか、\n需要ありますかね～…\nって冗談ですよ、冗談！", 10025, 2002, 133401, "2024/12/22 14:59:59");
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (7, 1, "2024/12/15 15:00:00", "グレイス", 2, 0, -470, 1.78, 1, "へい、らっしゃい\nさ、騎士氏。冥土の土産は\nなにがいいですか？", 10026, 2002, 133002, "2025/03/22 14:59:59");
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (7, 2, "2024/12/15 15:00:00", "グレイス", 1, 0, -470, 6.15, 7, "商品をお買い上げ毎に\nグレイスちゃんポイントを\n差し上げます。嘘ですが", 10027, 2002, 133002, "2025/03/22 14:59:59");
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (7, 1, "2024/12/15 15:00:00", "ヴァイオレット", 6, 0, -470, 4.28, 2, "ようこそいらっしゃいませ\n…接客とは、このような\n振舞で宜しいでしょうか？", 10028, 2002, 133102, "2025/03/22 14:59:59");
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (7, 2, "2024/12/15 15:00:00", "ヴァイオレット", 1, 0, -470, 0, 1, "じめじめした商品は\nございませんので\n安心してお買い求め下さい", 10029, 2002, 133102, "2025/03/22 14:59:59");
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (8, 1, "2025/03/15 15:00:00", "ルルィ", 2, 0, -470, 5.53, 1, "いらっしゃいましぇでしゅ\n何をお求めでしゅか？\nたこ焼きもありましゅよ！", 10030, 2002, 136902, "2025/06/23 14:59:59");
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (8, 2, "2025/03/15 15:00:00", "ルルィ", 9, 0, -470, 6.05, 7, "そのコイン…ピカピカで、\n集めたくなっちゃいましゅ\nタコ釣られされちゃう～…", 10031, 2002, 136902, "2025/06/23 14:59:59");
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (8, 1, "2025/03/15 15:00:00", "デュラン", 2, 0, -470, 0, 1, "姫のご友人ならば\n礼儀を尽くすのが爺の務め\nさ、望みの物を言いたまえ", 10032, 2002, 137001, "2025/06/23 14:59:59");
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (8, 2, "2025/03/15 15:00:00", "デュラン", 2, 0, -470, 0, 1, "キャラバンコインではなく\n首で支払って貰えんかのぅ\n…冗談であるぞ？", 10033, 2002, 137001, "2025/06/23 14:59:59");
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (9, 1, "2025/06/16 15:00:00", "サツキ", 2, 0, -470, 0, 2, "おう\n好きなもん持ってきな", 10034, 2002, 135902, "2025/09/23 14:59:59");
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (9, 2, "2025/06/16 15:00:00", "サツキ", 1, 0, -470, 4.935, 6, "宵越しの銭を持つような\n野暮いマネぁしくさんな\nツキが落ちてもしらねぇぜ", 10035, 2002, 135902, "2025/09/23 14:59:59");
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (9, 1, "2025/06/16 15:00:00", "ユキノ", 2, 0, -470, 7.441, 5, "ら、ら、らっしゃっせ…\nなんかほしいもん、ある？\nか、かき氷とか、ど…？", 10036, 2002, 135802, "2025/09/23 14:59:59");
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (9, 2, "2025/06/16 15:00:00", "ユキノ", 7, 0, -470, 0, 7, "そ、そんな見ねぇで…\nあては、売りもんじゃ\nねぇよ…？", 10037, 2002, 135802, "2025/09/23 14:59:59");
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (10, 1, "2025/09/16 15:00:00", "クルル", 2, 0, -470, 2.295, 2, "クルルをお求めですかっ？\nそれならお礼に、こちらの\n宝石もどうぞですよ～♪", 10038, 2002, 130901, "2025/12/22 14:59:59");
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (10, 2, "2025/09/16 15:00:00", "クルル", 1, 0, -470, 6.281, 6, "はっ！　ヒーローさんから\nお代なんて頂けないです！\nどうぞどうぞ…え、ダメ？", 10039, 2002, 130901, "2025/12/22 14:59:59");
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (10, 1, "2025/09/16 15:00:00", "ヴォルガーノ", 2, 0, -470, 5.549, 1, "よぅ！　今日の俺さまは\n門番じゃなく、店番だぜ\nメモピ～スフィア～てな！", 10040, 2002, 137701, "2025/12/22 14:59:59");
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (10, 2, "2025/09/16 15:00:00", "ヴォルガーノ", 3, 0, -470, 2.64, 6, "…リマさんのブロマイド？\n買い取るに決まってらぁ！\nなんでも持ってけ泥棒っ！", 10041, 2002, 137701, "2025/12/22 14:59:59");
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (11, 1, "2025/12/15 15:00:00", "ライラエル", 7, 0, -470, 7.642, 4, "こ、この格好は…ヴルムが\n集客効果があると言って…\n…本当でしょうか？", 10042, 2002, 132801, "2026/03/23 11:59:59");
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (11, 2, "2025/12/15 15:00:00", "ライラエル", 1, 0, -470, 0, 1, "この我に店番させるとは…\n全て買わねば許さぬぞ\n我が国庫に貢献するが良い", 10043, 2002, 132802, "2026/03/23 11:59:59");
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (11, 1, "2025/12/15 15:00:00", "クローチェ", 1, 0, -470, 0, 1, "アナライズっ！\n本日のオススメ商品は～…\nこちらですっ♪", 10044, 2002, 134502, "2026/03/23 11:59:59");
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (11, 2, "2025/12/15 15:00:00", "クローチェ", 2, 0, -470, 3.72, 1, "ギガンティックローチェ、\nおひとついかがですかっ？\n格納庫用意して下さいねっ", 10045, 2002, 134501, "2026/03/23 11:59:59");
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (12, 1, "2026/03/16 12:00:00", "ネフィ＝ネラ", 2, 0, -470, 4.991, 1, "番頭も、飯事の如き営み\nなれば。愛らしき稚児らで\n千客万来といきませぬか喃", 10046, 2002, 138201, "2026/06/22 11:59:59");
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (12, 2, "2026/03/16 12:00:00", "ネフィ＝ネラ", 1, 0, -470, 3.877, 4, "国を営むに金子は必須也…\nどうか御恵みくだしゃんせ\n誠心を以て報恩致しまする", 10047, 2002, 138201, "2026/06/22 11:59:59");
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (12, 1, "2026/03/16 12:00:00", "アラクネ", 4, 0, -470, 1.71, 6, "あぅっ…！　天井が低くて\n頭をぶつけてしまって…\nわたしが、大きいだけ…？", 10048, 2002, 136001, "2026/06/22 11:59:59");
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (12, 2, "2026/03/16 12:00:00", "アラクネ", 5, 0, -470, 5.32, 2, "いらっしゃいませ騎士さま\nくつろいでいって下さいね\nもし叶うなら…永遠に…", 10049, 2002, 136001, "2026/06/22 11:59:59");
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (13, 1, "2026/06/15 12:00:00", "アネモネ", 9, 0, -470, 3.727, 4, "水着で、店番とか──\n本当、意味がわかりません\n海の家でもないのに…", 10050, 2002, 135401, "2026/09/22 11:59:59");
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (13, 2, "2026/06/15 12:00:00", "アネモネ", 7, 0, -470, 7.213, 9, "──リアみたいに、\nもっと愛想良い接客を…\nいえ──なんでもないです", 10051, 2002, 135401, "2026/09/22 11:59:59");
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (13, 1, "2026/06/15 12:00:00", "クリア", 1, 0, -470, 1.874, 2, "いらっしゃいませー♪\n奉仕活動兼、将来のために\nたくさん働いちゃいます♪", 10052, 2002, 135301, "2026/09/22 11:59:59");
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (13, 2, "2026/06/15 12:00:00", "クリア", 2, 0, -470, 0, 2, "アルバイトが終わったら\n海に遊びに行きましょう！\nモネちゃんも一緒に♪", 10053, 2002, 135301, "2026/09/22 11:59:59");
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (14, 1, "2026/09/15 12:00:00", "ヴァイオレット", 2, 0, -470, 4.215, 1, "大いなる命、神なる勇魚…\n慈しみの矜持を胸に素敵な\n商品をお売りいたします", 10054, 2002, 138001, "2026/12/22 11:59:59");
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES (14, 2, "2026/09/15 12:00:00", "ヴァイオレット", 4, 0, -470, 0, 4, "すみません、わたくしの\n手料理は売り切れなのです\nグレイスが、買い占めを…", 10055, 2002, 138001, "2026/12/22 11:59:59");
